import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Commandes CLI","description":"","frontmatter":{},"headers":[],"relativePath":"fr/cli/overview.md","filePath":"fr/cli/overview.md","lastUpdated":1784903584000}'),r={name:"fr/cli/overview.md"};function c(i,e,s,n,l,u){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="commandes-cli" tabindex="-1">Commandes CLI <a class="header-anchor" href="#commandes-cli" aria-label="Permalink to &quot;Commandes CLI&quot;">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h2><p>La CLI <code>swag2mcp</code> est le point d&#39;entrée unique pour toutes les opérations — de l&#39;initialisation d&#39;un espace de travail et la gestion des spécifications API au démarrage d&#39;un serveur MCP pour l&#39;intégration LLM. Elle fournit <strong>13 commandes</strong> qui couvrent l&#39;ensemble du cycle de vie du travail avec les specs OpenAPI/Swagger/Postman.</p><h3 id="ce-que-la-cli-resout" tabindex="-1">Ce que la CLI résout <a class="header-anchor" href="#ce-que-la-cli-resout" aria-label="Permalink to &quot;Ce que la CLI résout&quot;">​</a></h3><ul><li><strong>Cycle de vie de l&#39;espace de travail</strong> — créer (<code>init</code>), inspecter (<code>info</code>, <code>ls</code>), nettoyer (<code>clean</code>), mettre à jour (<code>update</code>) et supprimer (<code>delete</code>) les espaces de travail et leur contenu</li><li><strong>Gestion des specs et collections</strong> — ajouter (<code>add</code>), lister (<code>ls</code>) et supprimer (<code>delete</code>) les spécifications API et leurs collections</li><li><strong>Modes d&#39;exécution</strong> — démarrer le serveur MCP pour l&#39;accès aux outils LLM (<code>mcp</code>) ou lancer l&#39;explorateur TUI interactif (<code>run</code>)</li><li><strong>Diagnostics</strong> — valider la configuration (<code>validate</code>), afficher la version (<code>version</code>), afficher les informations d&#39;exécution (<code>info</code>)</li><li><strong>Sauvegarde et restauration</strong> — transfert complet d&#39;espace de travail via ZIP (<code>export</code>, <code>import</code>)</li></ul><h3 id="nuances-cles" tabindex="-1">Nuances clés <a class="header-anchor" href="#nuances-cles" aria-label="Permalink to &quot;Nuances clés&quot;">​</a></h3><ul><li><strong>Résolution de chemin</strong> — les commandes qui acceptent <code>[chemin]</code> attendent un <strong>répertoire d&#39;espace de travail</strong> (pas un chemin de fichier). Ordre de résolution : <code>[chemin]</code> explicite → répertoire courant (<code>./</code>) → <code>~/.swag2mcp/</code>. La CLI ajoute <code>swag2mcp.yaml</code> automatiquement. Passez toujours un chemin explicite lorsque vous l&#39;exécutez comme service ou dans une configuration IDE pour éviter de charger le mauvais espace de travail.</li><li><strong>Spec vs Collection</strong> — une <strong>spec</strong> représente un service API logique (par exemple « API Open-Meteo »), tandis qu&#39;une <strong>collection</strong> est un fichier OpenAPI/Swagger/Postman. Une spec peut avoir plusieurs collections.</li><li><strong><code>--version</code></strong> est pris en charge à la fois comme drapeau (<code>swag2mcp --version</code>) et comme sous-commande (<code>swag2mcp version</code>).</li><li><strong><code>add spec</code> / <code>add collection</code></strong> acceptent une entrée YAML via <code>--yaml</code> (chaîne en ligne ou <code>-</code> pour stdin). L&#39;utilisation d&#39;un pipe depuis un fichier ou d&#39;un heredoc évite les problèmes de guillemets du shell avec les caractères spéciaux.</li><li><strong><code>delete</code></strong> nécessite un TTY (terminal interactif). Il n&#39;y a pas de drapeau <code>--force</code> ou <code>--yes</code> — il demande toujours une sélection et une confirmation.</li><li><strong><code>mcp</code></strong> est la commande principale pour l&#39;intégration LLM. Elle prend en charge trois transports : <code>stdio</code> (défaut), <code>sse</code> et <code>streamable-http</code>. Le drapeau <code>--disable-llm-auth</code> (défaut : <code>true</code>) supprime l&#39;outil <code>auth</code> de la liste des outils MCP, empêchant le LLM de voir ou de demander des jetons. L&#39;authentification fonctionne toujours — les jetons sont obtenus via le mécanisme de configuration standard, pas via le LLM. Ce mode est recommandé pour la <strong>production</strong> (le LLM n&#39;a jamais accès aux identifiants). Pour le <strong>débogage</strong> ou lors de l&#39;utilisation de jetons de courte durée, définissez <code>--disable-llm-auth=false</code> pour permettre au LLM de demander des jetons frais via l&#39;outil <code>auth</code>.</li><li><strong><code>validate</code></strong> vérifie la syntaxe YAML, la structure de la configuration, l&#39;existence des fichiers de spécification, l&#39;accessibilité des URL, le format de la spec (OpenAPI/Swagger/Postman), les paramètres d&#39;authentification et l&#39;exactitude du client HTTP. Il ne <strong>teste pas</strong> les points d&#39;accès d&#39;authentification ni la disponibilité des points d&#39;accès API.</li><li><strong><code>export</code> / <code>import</code></strong> fournissent un transfert complet d&#39;espace de travail — fichier de configuration, fichiers de spécification, cache et scripts d&#39;authentification sont tous inclus dans l&#39;archive ZIP.</li><li><strong><code>clean</code></strong> supprime les répertoires <code>cache/</code> et <code>responses/</code> mais préserve <code>specs/</code> et <code>auth_scripts/</code>. Les anciennes réponses (&gt;48h) sont également nettoyées automatiquement au démarrage de <code>mcp</code>.</li></ul><h2 id="commandes" tabindex="-1">Commandes <a class="header-anchor" href="#commandes" aria-label="Permalink to &quot;Commandes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Commande</th><th>Description</th></tr></thead><tbody><tr><td><a href="/cli/init"><code>init</code></a></td><td>Initialiser un répertoire d&#39;espace de travail avec la configuration par défaut</td></tr><tr><td><a href="/cli/add"><code>add</code></a></td><td>Ajouter une spec ou une collection à la configuration</td></tr><tr><td><a href="/cli/delete"><code>delete</code></a></td><td>Supprimer une spec ou une collection de manière interactive</td></tr><tr><td><a href="/cli/ls"><code>ls</code></a></td><td>Lister toutes les specs et leurs collections</td></tr><tr><td><a href="/cli/run"><code>run</code></a></td><td>Lancer l&#39;explorateur TUI interactif d&#39;API</td></tr><tr><td><a href="/cli/validate"><code>validate</code></a></td><td>Valider la configuration et les fichiers de spécification</td></tr><tr><td><a href="/cli/clean"><code>clean</code></a></td><td>Vider les specs en cache et les réponses d&#39;invocation</td></tr><tr><td><a href="/cli/update"><code>update</code></a></td><td>Revalider, re-mettre en cache et réindexer toutes les specs</td></tr><tr><td><a href="/cli/mcp"><code>mcp</code></a></td><td>Démarrer le serveur MCP pour l&#39;accès aux outils LLM</td></tr><tr><td><a href="/cli/version"><code>version</code></a></td><td>Afficher la version de swag2mcp</td></tr><tr><td><a href="/cli/info"><code>info</code></a></td><td>Afficher les informations détaillées de configuration et d&#39;exécution</td></tr><tr><td><a href="/cli/import"><code>import</code></a></td><td>Importer des fichiers de spécification ou restaurer l&#39;espace de travail depuis ZIP</td></tr><tr><td><a href="/cli/export"><code>export</code></a></td><td>Exporter l&#39;espace de travail comme sauvegarde ZIP portable</td></tr></tbody></table><h2 id="drapeaux-globaux" tabindex="-1">Drapeaux globaux <a class="header-anchor" href="#drapeaux-globaux" aria-label="Permalink to &quot;Drapeaux globaux&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Drapeau</th><th>Description</th></tr></thead><tbody><tr><td><code>--version</code></td><td>Afficher la version (identique à la sous-commande <code>version</code>)</td></tr><tr><td><code>--help</code></td><td>Afficher l&#39;aide pour n&#39;importe quelle commande</td></tr></tbody></table>',11)])])}const h=t(r,[["render",c]]);export{m as __pageData,h as default};
